CREATE TABLE "fiscal_certificates"("id" SERIAL PRIMARY KEY,"name" TEXT NOT NULL,"branch_id" INTEGER NOT NULL,"encrypted_content" TEXT NOT NULL,"encrypted_password" TEXT NOT NULL,"fingerprint" TEXT NOT NULL,"expires_at" DATE NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,"created_by" TEXT NOT NULL,"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),"updated_at" TIMESTAMPTZ NOT NULL DEFAULT now());CREATE INDEX "fiscal_certificates_branch_id_active_expires_at_idx" ON "fiscal_certificates"("branch_id","active","expires_at");
CREATE TABLE "fiscal_documents"("id" SERIAL PRIMARY KEY,"branch_id" INTEGER NOT NULL,"type" TEXT NOT NULL,"series" INTEGER NOT NULL,"number" INTEGER NOT NULL,"status" TEXT NOT NULL DEFAULT 'draft',"environment" TEXT NOT NULL DEFAULT 'homologation',"source_type" TEXT NOT NULL,"source_id" TEXT NOT NULL,"recipient" TEXT NOT NULL,"amount" DOUBLE PRECISION NOT NULL,"access_key" TEXT,"protocol" TEXT,"rejection_code" TEXT,"rejection_message" TEXT,"issued_at" TIMESTAMPTZ,"cancelled_at" TIMESTAMPTZ,"created_by" TEXT NOT NULL,"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),"updated_at" TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE("branch_id","type","series","number"),UNIQUE("source_type","source_id","type"));CREATE INDEX "fiscal_documents_status_created_at_idx" ON "fiscal_documents"("status","created_at");
CREATE TABLE "fiscal_events"("id" SERIAL PRIMARY KEY,"document_id" INTEGER NOT NULL REFERENCES "fiscal_documents"("id") ON DELETE CASCADE,"type" TEXT NOT NULL,"code" TEXT,"description" TEXT NOT NULL,"actor" TEXT NOT NULL,"created_at" TIMESTAMPTZ NOT NULL DEFAULT now());CREATE INDEX "fiscal_events_document_id_created_at_idx" ON "fiscal_events"("document_id","created_at");
CREATE TABLE "automation_rules"("id" SERIAL PRIMARY KEY,"name" TEXT NOT NULL,"trigger" TEXT NOT NULL,"condition_field" TEXT NOT NULL,"operator" TEXT NOT NULL,"condition_value" TEXT NOT NULL,"action_type" TEXT NOT NULL,"action_config" JSONB,"active" BOOLEAN NOT NULL DEFAULT true,"created_by" TEXT NOT NULL,"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),"updated_at" TIMESTAMPTZ NOT NULL DEFAULT now());CREATE INDEX "automation_rules_active_trigger_idx" ON "automation_rules"("active","trigger");
CREATE TABLE "automation_runs"("id" SERIAL PRIMARY KEY,"rule_id" INTEGER NOT NULL REFERENCES "automation_rules"("id") ON DELETE CASCADE,"idempotency_key" TEXT NOT NULL UNIQUE,"status" TEXT NOT NULL,"matched_count" INTEGER NOT NULL DEFAULT 0,"action_count" INTEGER NOT NULL DEFAULT 0,"error_message" TEXT,"started_at" TIMESTAMPTZ NOT NULL DEFAULT now(),"finished_at" TIMESTAMPTZ);CREATE INDEX "automation_runs_rule_id_started_at_idx" ON "automation_runs"("rule_id","started_at");
CREATE TABLE "automation_notifications"("id" SERIAL PRIMARY KEY,"rule_id" INTEGER NOT NULL REFERENCES "automation_rules"("id") ON DELETE CASCADE,"subject" TEXT NOT NULL,"message" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'unread',"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),"read_at" TIMESTAMPTZ);CREATE INDEX "automation_notifications_status_created_at_idx" ON "automation_notifications"("status","created_at");
CREATE TABLE "legal_bases"("id" SERIAL PRIMARY KEY,"name" TEXT NOT NULL,"basis" TEXT NOT NULL,"purpose" TEXT NOT NULL,"data_category" TEXT NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,"created_at" TIMESTAMPTZ NOT NULL DEFAULT now());CREATE INDEX "legal_bases_active_data_category_idx" ON "legal_bases"("active","data_category");
CREATE TABLE "retention_rules"("id" SERIAL PRIMARY KEY,"data_category" TEXT NOT NULL UNIQUE,"retention_days" INTEGER NOT NULL,"legal_reason" TEXT NOT NULL,"action" TEXT NOT NULL DEFAULT 'anonymize',"active" BOOLEAN NOT NULL DEFAULT true,"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),"updated_at" TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE "privacy_requests"("id" SERIAL PRIMARY KEY,"number" TEXT NOT NULL UNIQUE,"type" TEXT NOT NULL,"subject_name" TEXT NOT NULL,"subject_document" TEXT NOT NULL,"contact" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'received',"due_at" DATE NOT NULL,"verified_at" TIMESTAMPTZ,"completed_at" TIMESTAMPTZ,"evidence" TEXT,"assigned_to" TEXT,"created_by" TEXT NOT NULL,"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),"updated_at" TIMESTAMPTZ NOT NULL DEFAULT now());CREATE INDEX "privacy_requests_status_due_at_idx" ON "privacy_requests"("status","due_at");
CREATE TABLE "privacy_incidents"("id" SERIAL PRIMARY KEY,"title" TEXT NOT NULL,"severity" TEXT NOT NULL,"description" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'open',"affected_subjects" INTEGER NOT NULL DEFAULT 0,"reported_at" TIMESTAMPTZ NOT NULL DEFAULT now(),"resolved_at" TIMESTAMPTZ,"created_by" TEXT NOT NULL);CREATE INDEX "privacy_incidents_status_severity_reported_at_idx" ON "privacy_incidents"("status","severity","reported_at");
